  + name : string
}

class City {
  + name : string
}

class RoomType {
  + type : string
}

class Booking {
  + bookingIdentifier : string
  + arrivalDate : date
  + departureDate : date
  + numRooms : int
  + roomType : RoomType
  + maxCostPerNight : float
  + status : string
  + cancellationDeadline : date
}

class PreliminaryBooking {
  + price : float
  + cityArea : string
  + hotelRating : int
  + keyPreferences : string[]
}

class SpecialOffer {
  + price : float
}

class PaymentMethod {
  + creditCardInfo : string
}

enum PaymentStatus {
  PRE_PAID
  PAID_AT_HOTEL
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numRooms : int
  + roomType : string
  + minRating : int
  + maxCostPerNight : float
  + preferences : string[]
}

Traveller "1" -- "*" Booking : makes
Traveller "1" -- "*" PreliminaryBooking : creates
Hotel "0..*" -- "1" City : located in
Hotel "0..*" -- "0..1" HotelChain : run by
Hotel "1" -- "*" Booking : confirms
Hotel "1" -- "*" SpecialOffer : provides
Hotel "1" -- "*" RoomType : offers
Booking "1" -- "1" PaymentMethod : uses
Booking "1" -- "0..1" SpecialOffer : can switch to
PreliminaryBooking "1" -- "0..*" SpecialOffer : generates
PreliminaryBooking "1" -- "1" Booking : converts to
Booking "1" -- "1" PaymentStatus : has

@enduml

